pub fn check_auth(
    authorization: Option<&str>,
    cookie: Option<&str>,
    api_key_header: Option<&str>,
    query: Option<&str>,
    method: &str,
    path: &str,
    is_https: bool,
    rng_seed: u32,
) -> AuthResult {
    // Extract only the auth-relevant fields (avoid cloning full AppSettings
    // which is ~2 KB and would blow the task stack).
    let auth = crate::state::with_settings(|s| s.auth.clone());

    // Public access -- allow everything
    if auth.public_access {
        return AuthResult::Allowed;
    }

    // Always allow the health endpoint (monitoring probes)
    if path == "/api/health" {
        return AuthResult::Allowed;
    }

    // Check bearer/API-key transport security
    let allow_http_tokens = auth.allow_http_tokens;

    // --- Session cookie ---
    if let Some(cookie_hdr) = cookie {
        if let Some(token) = extract_cookie(cookie_hdr, "__session") {
            if let Some(decrypted) = decrypt_session_cookie(token) {
                if validate_session(&decrypted) {
                    return AuthResult::Allowed;
                }
            }
        }
    }

    // --- Bearer token ---
    if let Some(hdr) = authorization {
        if let Some(token) = hdr.strip_prefix("Bearer ").or_else(|| hdr.strip_prefix("bearer ")) {
            if !is_https && !allow_http_tokens {
                return AuthResult::Forbidden;
            }
            if !auth.bearer_token.is_empty()
                && constant_time_eq(token.as_bytes(), auth.bearer_token.as_bytes())
            {
                return AuthResult::Allowed;
            }
        }
    }

    // --- API Key (header) ---
    if let Some(key) = api_key_header {
        if !is_https && !allow_http_tokens {
            return AuthResult::Forbidden;
        }
        if !auth.api_key.is_empty()
            && constant_time_eq(key.as_bytes(), auth.api_key.as_bytes())
        {
            return AuthResult::Allowed;
        }
    }

    // --- API Key (query param) ---
    if let Some(qs) = query {
        if let Some(key) = extract_query_param(qs, "api_key") {
            if !is_https && !allow_http_tokens {
                return AuthResult::Forbidden;
            }
            if !auth.api_key.is_empty()
                && constant_time_eq(key.as_bytes(), auth.api_key.as_bytes())
            {
                return AuthResult::Allowed;
            }
        }
    }

    // --- Digest auth ---
    if let Some(hdr) = authorization {
        if hdr.len() > 7 && hdr[..7].eq_ignore_ascii_case("Digest ") {
            if verify_digest(hdr, method) {
                let token = create_session(rng_seed);
                return AuthResult::AllowedSetSession(token);
            }
        }
    }

    // No valid credentials -- issue Digest challenge
    AuthResult::Challenge(digest_challenge())
}

Command.kernel_code:
pub enum Command {
    /// `POST /api/ota/begin/{size}` — open a session for `size` bytes.
    Begin { size: u32 },
    /// `POST /api/ota/write/{offset}` — write a `len`-byte chunk at `offset`.
    /// `io_ok`: whether the flash erase + program of the chunk succeeded
    /// (trusted IO, done only for a chunk the kernel would commit).
    Write { offset: u32, len: u32, io_ok: bool },
    /// `GET /api/ota/end/{expected_crc}` — verify and activate. The trusted
    /// IO results: `read_ok` (the image read back from flash), `magic_ok`
    /// (its first byte), `actual_crc` (its CRC-32), `activate_ok` (otadata
    /// written; done only when the rest verified).
    End { expected_crc: u32, actual_crc: u32, magic_ok: bool, read_ok: bool, activate_ok: bool },
    /// `GET /api/ota/abort`.
    Abort,
    /// `GET /api/ota/status`.
    Status,
}

