async fn ota_end_handler(expected_crc: u32, auth: crate::auth::Authenticated) -> impl picoserve::response::IntoResponse {
    REQUEST_COUNT.fetch_add(1, Ordering::Relaxed);
    log::info!("OTA end requested (expected CRC=0x{:08X})", expected_crc);
    let j = crate::ota::end(expected_crc);
    // Note: we can't reboot here because the response hasn't been sent yet.
    // Instead, spawn_reboot_delayed() sets a flag checked by the heartbeat
    // loop, which reboots after a short delay.  If we're on HTTPS the
    // https_route handler does the reboot after the response flushes.
    if j.contains(r#""ok":true"#) {
        log::info!("[ota] scheduling reboot (picoserve path)");
        spawn_reboot_delayed();
    }
    (auth, ("Content-Type", "application/json"), j)
}

