    log::info!("OTA begin: size={}", size);
    let j = crate::ota::begin(size);
    (auth, ("Content-Type", "application/json"), j)
}

async fn ota_write_handler(offset: u32, auth: crate::auth::Authenticated, body: alloc::vec::Vec<u8>) -> impl picoserve::response::IntoResponse {
    let j = crate::ota::write(offset, &body);
    (auth, ("Content-Type", "application/json"), j)
}

async fn ota_end_handler(expected_crc: u32, auth: crate::auth::Authenticated) -> impl picoserve::response::IntoResponse {
    REQUEST_COUNT.fetch_add(1, Ordering::Relaxed);
    log::info!("OTA end requested (expected CRC=0x{:08X})", expected_crc);
    let j = crate::ota::end(expected_crc);
    // Note: we can't reboot here because the response hasn't been sent yet.
    // Instead, spawn_reboot_delayed() sets a flag checked by the heartbeat
    // loop, which reboots after a short delay.  If we're on HTTPS the
    // https_route handler does the reboot after the response flushes.
    if j.contains(r#""ok":true"#) {
        log::info!("[ota] scheduling reboot (picoserve path)");
        spawn_reboot_delayed();
    }
    (auth, ("Content-Type", "application/json"), j)
}

async fn ota_abort_handler(auth: crate::auth::Authenticated) -> impl picoserve::response::IntoResponse {
    REQUEST_COUNT.fetch_add(1, Ordering::Relaxed);
    log::info!("OTA abort requested");
    let j = crate::ota::abort();
    (auth, ("Content-Type", "application/json"), j)
}

pub fn status() -> String {
    let active = OTA_ACTIVE.load(Ordering::Relaxed);
    let slot = OTA_TARGET_SLOT.load(Ordering::Relaxed);
    let total = OTA_TOTAL_SIZE.load(Ordering::Relaxed);
    let written = OTA_WRITTEN.load(Ordering::Relaxed);
    let error = OTA_ERROR.load(Ordering::Relaxed);
    let pct = if total > 0 { written * 100 / total } else { 0 };

    // Also report active slot.
    let active_slot = if active {
        1 - slot // the other slot is the currently running one
    } else {
        // Read from flash only when no OTA is in progress.
        critical_section::with(|cs| {
            let mut borrow = crate::state::STATE.borrow_ref_mut(cs);
            let inner = borrow.as_mut().unwrap();
            read_active_slot(&mut inner.store.flash)
        })
    };

    format!(
        r#"{{"active_slot":{},"ota_in_progress":{},"target_slot":{},"written":{},"total":{},"pct":{},"error":{}}}"#,
        active_slot, active, slot, written, total, pct, error
    )
}

