pub fn begin(firmware_size: u32) -> String {
    if OTA_ACTIVE.load(Ordering::Relaxed) {
        return format!(r#"{{"ok":false,"error":"OTA already in progress"}}"#);
    }
    if firmware_size == 0 || firmware_size > OTA_SLOT_SIZE {
        return format!(
            r#"{{"ok":false,"error":"invalid size (max {} bytes)"}}"#,
            OTA_SLOT_SIZE
        );
    }

    // Determine running slot (detected at boot via flash fingerprinting)
    // and target the OTHER slot.  This is critical -- targeting the running
    // slot would erase the firmware we're executing from.
    let running = RUNNING_SLOT.load(Ordering::Relaxed);
    if running == 0xFF {
        // init_running_slot() was never called -- refuse rather than guess.
        return format!(r#"{{"ok":false,"error":"running slot unknown (call init_running_slot at boot)"}}"#);
    }
    let target = 1 - running;

    // Also log what otadata thinks (for diagnostics).
    let otadata_active = critical_section::with(|cs| {
        let mut borrow = crate::state::STATE.borrow_ref_mut(cs);
        let inner = borrow.as_mut().unwrap();
        read_active_slot(&mut inner.store.flash)
    });
    if otadata_active != running {
        log::warn!(
            "[ota] otadata says slot {} active, but we detected slot {} as running",
            otadata_active, running
        );
    }

    let num_sectors = (firmware_size + FLASH_SECTOR_SIZE - 1) / FLASH_SECTOR_SIZE;

    log::info!(
        "[ota] begin: size={}B running=slot{} target=slot{} (0x{:05X}), {} sectors (lazy erase)",
        firmware_size,
        running,
        target,
        slot_offset(target),
        num_sectors,
    );

    // Mark session active. Sectors will be erased on-demand in write().
    OTA_TARGET_SLOT.store(target, Ordering::Relaxed);
    OTA_TOTAL_SIZE.store(firmware_size, Ordering::Relaxed);
    OTA_WRITTEN.store(0, Ordering::Relaxed);
    OTA_ERROR.store(false, Ordering::Relaxed);
    OTA_ACTIVE.store(true, Ordering::Release);

    format!(
        r#"{{"ok":true,"slot":{},"size":{},"sectors":{}}}"#,
        target, firmware_size, num_sectors
    )
}

pub fn write(offset: u32, data: &[u8]) -> String {
    if !OTA_ACTIVE.load(Ordering::Acquire) {
        return format!(r#"{{"ok":false,"error":"no OTA session"}}"#);
    }
    if OTA_ERROR.load(Ordering::Relaxed) {
        return format!(r#"{{"ok":false,"error":"OTA aborted due to prior error"}}"#);
    }
    if data.is_empty() || data.len() > MAX_CHUNK_SIZE {
        return format!(r#"{{"ok":false,"error":"chunk too large (max {})"}}"#, MAX_CHUNK_SIZE);
    }

    let expected = OTA_WRITTEN.load(Ordering::Relaxed);
    let total = OTA_TOTAL_SIZE.load(Ordering::Relaxed);

    // Retry handling: if this chunk was already written (response lost but
    // data committed), return success so the client can continue.
    if offset < expected && offset + data.len() as u32 <= expected {
        return format!(
            r#"{{"ok":true,"written":{},"total":{},"pct":{}}}"#,
            expected, total, expected * 100 / total
        );
    }
    if offset != expected {
        return format!(
            r#"{{"ok":false,"error":"offset mismatch (expected {}, got {})"}}"#,
            expected, offset
        );
    }
    if offset + data.len() as u32 > total {
        return format!(r#"{{"ok":false,"error":"write exceeds declared size"}}"#);
    }

    let slot = OTA_TARGET_SLOT.load(Ordering::Relaxed);

    // Lazy erase: erase any sector that this chunk touches (before writing).
    // Chunks are sequential and up to 4KB (= 1 sector), so at most 2 sectors
    // can be touched (when a chunk straddles a sector boundary).
    let first_sector = offset / FLASH_SECTOR_SIZE;
    let last_sector = (offset + data.len() as u32 - 1) / FLASH_SECTOR_SIZE;
    for sector in first_sector..=last_sector {
        let er = critical_section::with(|cs| {
            let mut borrow = crate::state::STATE.borrow_ref_mut(cs);
            let inner = borrow.as_mut().unwrap();
            erase_slot_sector(&mut inner.store.flash, slot, sector)
        });
        if let Err(e) = er {
            OTA_ERROR.store(true, Ordering::Relaxed);
            log::error!("[ota] erase failed at sector {}: {}", sector, e);
            return format!(r#"{{"ok":false,"error":"erase failed at sector {}"}}"#, sector);
        }
    }

    // Pad data to 4-byte alignment for NorFlash write.
    let mut chunk = alloc::vec![0xFF_u8; (data.len() + 3) & !3];
    chunk[..data.len()].copy_from_slice(data);

    let r = critical_section::with(|cs| {
        let mut borrow = crate::state::STATE.borrow_ref_mut(cs);
        let inner = borrow.as_mut().unwrap();
        write_chunk(&mut inner.store.flash, slot, offset, &chunk)
    });

    if let Err(e) = r {
        OTA_ERROR.store(true, Ordering::Relaxed);
        log::error!("[ota] write failed at offset {}: {}", offset, e);
        return format!(r#"{{"ok":false,"error":"{}"}}"#, e);
    }

    let new_written = offset + data.len() as u32;
    OTA_WRITTEN.store(new_written, Ordering::Relaxed);

    format!(
        r#"{{"ok":true,"written":{},"total":{},"pct":{}}}"#,
        new_written,
        total,
        new_written * 100 / total,
    )
}

pub fn end(expected_crc: u32) -> String {
    if !OTA_ACTIVE.load(Ordering::Acquire) {
        return format!(r#"{{"ok":false,"error":"no OTA session"}}"#);
    }

    let written = OTA_WRITTEN.load(Ordering::Relaxed);
    let total = OTA_TOTAL_SIZE.load(Ordering::Relaxed);
    if written != total {
        return format!(
            r#"{{"ok":false,"error":"incomplete ({}/{} bytes)"}}"#,
            written, total
        );
    }

    let slot = OTA_TARGET_SLOT.load(Ordering::Relaxed);

    // Verify image header.
    let verify = critical_section::with(|cs| {
        let mut borrow = crate::state::STATE.borrow_ref_mut(cs);
        let inner = borrow.as_mut().unwrap();
        verify_image_header(&mut inner.store.flash, slot)
    });
    if let Err(e) = verify {
        OTA_ERROR.store(true, Ordering::Relaxed);
        OTA_ACTIVE.store(false, Ordering::Release);
        log::error!("[ota] image verification failed: {}", e);
        return format!(r#"{{"ok":false,"error":"{}"}}"#, e);
    }

    // Read back the entire image from flash and compute CRC-32.
    // Uses many short critical sections (one per 4 KB chunk) so WiFi
    // isn't starved during the ~1 MB read-back.
    log::info!("[ota] verifying CRC-32 ({} bytes from slot {})...", total, slot);
    let crc_result = compute_image_crc32_yielding(slot, total);
    match crc_result {
        Err(e) => {
            OTA_ERROR.store(true, Ordering::Relaxed);
            OTA_ACTIVE.store(false, Ordering::Release);
            log::error!("[ota] CRC read-back failed: {}", e);
            return format!(r#"{{"ok":false,"error":"{}"}}"#, e);
        }
        Ok(actual_crc) => {
            if actual_crc != expected_crc {
                OTA_ERROR.store(true, Ordering::Relaxed);
                OTA_ACTIVE.store(false, Ordering::Release);
                log::error!(
                    "[ota] CRC mismatch: expected 0x{:08X}, got 0x{:08X}",
                    expected_crc, actual_crc
                );
                return format!(
                    r#"{{"ok":false,"error":"CRC mismatch (expected {:08x}, got {:08x})"}}"#,
                    expected_crc, actual_crc
                );
            }
            log::info!("[ota] CRC-32 verified: 0x{:08X}", actual_crc);
        }
    }

    // Activate the new slot.
    let activate = critical_section::with(|cs| {
        let mut borrow = crate::state::STATE.borrow_ref_mut(cs);
        let inner = borrow.as_mut().unwrap();
        activate_slot(&mut inner.store.flash, slot)
    });
    if let Err(e) = activate {
        OTA_ERROR.store(true, Ordering::Relaxed);
        OTA_ACTIVE.store(false, Ordering::Release);
        log::error!("[ota] activation failed: {}", e);
        return format!(r#"{{"ok":false,"error":"{}"}}"#, e);
    }

    OTA_ACTIVE.store(false, Ordering::Release);
    log::info!("[ota] complete -- rebooting to slot {} ({}B)", slot, total);

    // Reboot after a short delay to let the HTTP response be sent.
    // The caller should send the response, then we reboot.
    format!(
        r#"{{"ok":true,"msg":"OTA complete, rebooting to slot {}","size":{}}}"#,
        slot, total
    )
}

pub fn abort() -> String {
    if !OTA_ACTIVE.load(Ordering::Acquire) {
        return format!(r#"{{"ok":false,"error":"no OTA session to abort"}}"#);
    }
    OTA_ACTIVE.store(false, Ordering::Release);
    OTA_ERROR.store(false, Ordering::Relaxed);
    OTA_WRITTEN.store(0, Ordering::Relaxed);
    log::info!("[ota] session aborted by user");
    format!(r#"{{"ok":true,"msg":"OTA aborted"}}"#)
}

