pub fn ct_eq8(a: &[u8; 8], b: &[u8; 8]) -> bool {
    let mut diff: u8 = 0;
    diff |= a[0] ^ b[0];
    diff |= a[1] ^ b[1];
    diff |= a[2] ^ b[2];
    diff |= a[3] ^ b[3];
    diff |= a[4] ^ b[4];
    diff |= a[5] ^ b[5];
    diff |= a[6] ^ b[6];
    diff |= a[7] ^ b[7];
    diff == 0
}

